function watchCards(){
 const pool=watchedPlayers(),autoState=pool.some(p=>p.game?.state==='in')?'in':pool.some(p=>p.game?.state==='pre')?'pre':null;
 const cards=pool.filter(p=>(filter==='all'||filter==='auto'&&(!autoState||p.game?.state===autoState)||filter==='pinned'&&pins.has(p.id)||filter==='live'&&p.game?.state==='in'||filter==='upcoming'&&p.game?.state==='pre'||filter==='done'&&p.game?.state==='post')&&`${pname(p.id)} ${p.player.team} ${p.player.number||''} ${p.player.position}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>(pins.has(b.id)-pins.has(a.id))||({in:0,pre:1,post:2}[a.game?.state]??3)-({in:0,pre:1,post:2}[b.game?.state]??3)||pname(a.id).localeCompare(pname(b.id)));
 queueMicrotask(()=>{if($('#player-count'))$('#player-count').textContent=cards.length});
 return cards.map(({id,player:p,game:g,appearances})=>{
  const state=g?.state,live=state==='in',label=live?'LIVE':state==='pre'?'UP NEXT':state==='post'?'FINAL':'NO GAME';
  const changes=appearances.map(a=>recentScore(id,a)).filter(Boolean),increase=changes.some(e=>e.delta>0),against=changes.filter(e=>e.delta>0).every(e=>e.side==='opponent'),preview=previewPlayer===id,effect=prefs.scoreEffects!==false&&(increase||preview);
  return `<article class="player-card compact-card ${effect?'score-up':''} ${effect&&against&&!preview?'opponent-update':''}" data-player-id="${esc(id)}" style="--team:${teamColors[p.team]||'#567587'}"><div class="compact-player"><div class="player-main">${playerPortrait(id,p)}<div class="player-identity"><div class="player-name" title="${esc(pname(id))}">${esc(pname(id))}</div><div class="player-meta">${esc(p.team||'FA')} · ${esc(p.position)}${p.injury_status?` · <strong class="attention">${esc(p.injury_status)}</strong>`:''}</div></div></div><button class="pin ${pins.has(id)?'on':''}" data-pin="${esc(id)}" aria-label="${pins.has(id)?'Unpin':'Pin'} ${esc(pname(id))}" aria-pressed="${pins.has(id)}">${pins.has(id)?'★':'☆'}</button></div><div class="compact-game"><span class="game-status ${live?'is-live':''}">${label}</span><span title="${esc(g?.detail||'Schedule unavailable')}">${g?`${g.home?'vs':'@'} ${esc(g.opponent)} · ${esc(g.detail)}${g.channel?' · '+esc(g.channel):''}`:'Schedule unavailable'}</span>${preview?'<span class="score-change">PREVIEW</span>':''}</div><div class="compact-score-head"><span>LEAGUE</span><span>PTS / PROJ</span></div>${appearances.map(a=>{
   const l=data.leagues.find(l=>l.league_id===a.leagueId),projection=value(id,l),change=recentScore(id,a),progress=Number.isFinite(a.points)&&projection>0?Math.min(100,Math.max(0,a.points/projection*100)):null;
   return `<div class="compact-score-row ${a.side==='opponent'?'against':''}"><div class="compact-league"><span class="role-dot" title="${a.side==='opponent'?'Opponent':a.side==='watch'?'Watchlist':a.starter?'Starter':'Bench'}"></span><span title="${esc(a.league)}">${esc(a.league)}</span>${!a.starter?'<small>BN</small>':''}${a.side==='opponent'?'<small>OPP</small>':''}</div><div class="compact-points">${change?`<span class="score-change ${change.delta<0?'correction':''}" title="${change.delta<0?'Score correction':'Since previous refresh'}">${signed(change.delta)}</span>`:''}<strong title="${esc(a.league)} actual points">${fmt(a.points,2)}</strong><span title="Pregame projection for ${esc(a.league)}"> / ${fmt(projection)}</span></div>${progress!==null?`<div class="projection-progress" aria-hidden="true"><span style="width:${progress}%"></span></div>`:''}</div>`;
  }).join('')}</article>`;
 }).join('')||empty('No players in this view',filter==='live'?'No tracked games are live right now. Try Game day or All players.':'Try another filter or include your bench.');
}

function lockedLineup(l){return sharedLocks(data,l)}
function usableValue(id,l,lockedIds=[]){return sharedValue(data,l,id,lockedIds)}
function lineup(){
 const l=league(),slots=activeSlots(l),{ids,locks}=lockedLineup(l),fixed=Object.values(locks),v=id=>usableValue(id,l,fixed);
 let best;try{best=lineupResults.get(JSON.stringify(weeklyAnalysisKey(l)),()=>optimize(playableIds(l.mine),slots,data.players,v,locks,ids))}catch(e){return analysisHeader('Start / sit','Compare your starters and bench, using this league’s scoring.')+empty(e.message)}
 const {starters,baseline,bench:benchPlayers}=lineupComparisons(data,l),complete=best.complete&&baseline!==null;
 const unknown=playableIds(l.mine).filter(id=>value(id,l)===null);
 const deltaLabel=n=>Number.isFinite(n)?`${signed(n)} pts`:'Unavailable';
 const deltaClass=n=>Number.isFinite(n)?n>0?'gain':n<0?'loss':'muted':'muted';
 const playerLabel=id=>!id||id==='0'?'Empty slot':pname(id);
 const playerInfo=id=>id&&id!=='0'?`<div class="small muted">${esc(data.players[id]?.team||'FA')} · ${esc(data.players[id]?.position||'Unknown')}${data.players[id]?.injury_status?` · ${esc(data.players[id].injury_status)}`:''}</div>`:'';
 const optionRow=option=>`<div class="bench-comparison"><span>${esc(option.slot)} · ${esc(playerLabel(option.id))}<span class="muted"> (${fmt(option.projection)} pts)</span></span><strong class="num ${deltaClass(option.delta)}">${deltaLabel(option.delta)}</strong></div>`;
 return analysisHeader('Start / sit','Compare your starters and bench, using this league’s scoring.')+`
 ${unknown.length?`<p class="data-alert">${unknown.length} rostered player(s) have no projection. Review them before following the optimizer.</p>`:''}
 <div class="panel decision lineup-summary"><div><div class="eyebrow">PROJECTED LINEUP IMPROVEMENT</div><h2>${complete?`${deltaLabel(best.total-baseline)}`:'Partial lineup estimate'}</h2><p class="muted small">${Object.keys(locks).length} started slots locked · unavailable players excluded from new starts</p></div><div class="lineup-totals"><div><div class="big-number">${fmt(baseline)}</div><div class="muted small">current projection</div></div><div><div class="big-number">${best.complete?fmt(best.total):'—'}</div><div class="muted small">optimized projection</div></div></div></div>
 <div class="panel table-wrap"><table class="lineup-table"><thead><tr><th scope="col">SLOT</th><th scope="col">CURRENT STARTER</th><th scope="col">RECOMMENDED</th><th scope="col">POINT DIFFERENCE</th><th scope="col">DECISION</th></tr></thead><tbody>${starters.map(({slot,index:i,projection,locked:lock})=>{
  const id=best.ids[i],same=id===ids[i],points=id?value(id,l):null,delta=Number.isFinite(points)&&Number.isFinite(projection)?points-projection:null;
  return `<tr><td><strong>${esc(slot)}</strong></td><td>${playerChip(ids[i],`${playerInfo(ids[i])}<div class="num small">${fmt(projection)} projected pts</div>`,'span')}</td><td>${playerChip(id,`${playerInfo(id)}<div class="num small">${fmt(points)} projected pts</div>`)}</td><td class="num ${deltaClass(delta)}">${deltaLabel(delta)}</td><td><span class="pill ${!same&&!lock&&id?'live':''}">${lock?'LOCKED':same?'KEEP':id?'SWAP IN':'NO PROJECTION'}</span></td></tr>`;
 }).join('')}</tbody></table></div>
 <div class="section-bar"><h2>Your bench <span class="count">${benchPlayers.length}</span></h2></div>
 <p class="muted small">Each difference is bench projection minus current starter projection. Positive means more expected points. Swaps are alternatives; don’t add their gains together.</p>
 <div class="lineup-bench">${benchPlayers.map(({id,projection,reason,options})=>`<article class="panel bench-player"><div class="bench-player-head">${playerChip(id,playerInfo(id),'h3')}<div class="bench-projection num"><strong>${fmt(projection)}</strong><span class="muted small">projected pts</span></div></div>${best.ids.includes(id)?'<p class="gain small">Recommended to start</p>':''}${reason?`<p class="muted small">${esc(reason)}</p>`:`<div class="small muted">Best direct swap · compared with</div>${optionRow(options[0])}${options.length>1?`<details class="bench-alternatives"><summary>Compare ${options.length-1} other eligible slot${options.length>2?'s':''}</summary>${options.slice(1).map(optionRow).join('')}</details>`:''}`}</article>`).join('')||'<p class="muted small">No bench players on this roster.</p>'}</div>
 <p class="muted small">Pregame estimates, not a live score forecast or betting spread. Bench comparisons replace one starter; the optimized lineup can also move players between flex slots. IR and taxi players are excluded. Make lineup changes in Sleeper.</p>${!data.demo?`<a class="secondary" href="https://sleeper.com/leagues/${esc(l.league_id)}/team" target="_blank" rel="noopener">Open league in Sleeper ↗</a>`:''}`;
}
function weeklyAnalysisKey(l){return [data.user.user_id,data.nfl?.season,data.week,rosterKey(l),identity(data.players),identity(data.projections[data.week]),
 lockedLineup(l),Object.entries(data.games).map(([team,g])=>[team,g.state])];}
function waiverWindow(){return waiverWeeks(data.week,waiverHorizon,data.demo?Math.min(waiverEndWeek,6):waiverEndWeek)}
function waiverKey(){return JSON.stringify([data.user.user_id,data.nfl?.season,waiverWindow()])}
async function ensureWaiverOutlook(force=false){
 if(waiverHorizon==='current')return;
 const key=waiverKey(),weeks=waiverWindow();
 if(waiverState?.key===key&&!force&&(waiverState.loading||waiverState.outlook&&Date.now()-waiverState.outlook.loadedAt<3600000))return;
 const cached=waiverOutlooks.peek(key);
 if(!force&&cached&&Date.now()-cached.loadedAt<3600000){waiverState={key,outlook:cached};if(view==='waivers')render();return}
 const state={key,loading:true,outlook:null,error:null};waiverState=state;if(view==='waivers')render();
 try{
  if(!weeks.length)throw Error('No future weeks remain in this window.');
  const outlook=data.demo?{weeks,data:Object.fromEntries(weeks.map(w=>[w,{projections:data.projections[w],games:data.schedules[w]}])),loadedAt:Date.now(),errors:[]}:await api.tradeOutlook(data.nfl.season,weeks,()=>{},force);
  if(outlook.errors.length)throw Error(`Missing projections or schedules for week(s) ${outlook.errors.join(', ')}. Recommendations are paused.`);
  state.outlook=outlook;waiverOutlooks.set(key,outlook);
 }catch(e){state.error=e.message}finally{state.loading=false;if(waiverState===state&&view==='waivers')render()}
}
function waiverRows(){
 const l=league(),future=waiverHorizon!=='current',outlook=waiverState?.key===waiverKey()?waiverState.outlook:null;
 if(future&&!outlook)return [];
 const key=JSON.stringify([...weeklyAnalysisKey(l),waiverHorizon,identity(outlook),identity(data.trends),waiverExcluded,protectedPlayers(l),protectStarters,samePositionDrops]);
 return waiverResults.get(key,()=>future?futureWaiverRows(l,outlook):computeWaiverRows());
}
function futureWaiverRows(l,outlook){
 const trending=new Map(data.trends.map(t=>[t.player_id,t.count])),slots=activeSlots(l);
 const model=buildWaiverOutlook({league:l,players:data.players,outlook,protectedIds:protectedPlayers(l),starterIds:protectStarters?lockedLineup(l).ids:[],excludedDropPositions:waiverExcluded.drop,samePosition:samePositionDrops});
 const free=tradeCandidateIds(availableIds(l,data.players),data.players,waiverExcluded.add).filter(id=>slots.some(slot=>eligible(data.players[id],slot)));
 const candidates=[...new Set([...free.filter(id=>trending.has(id)).sort((a,b)=>trending.get(b)-trending.get(a)).slice(0,30),...free.filter(id=>model.totals[id]>0).sort((a,b)=>model.totals[b]-model.totals[a]).slice(0,35)])];
 return candidates.map(id=>({id,count:trending.get(id)||0,projection:model.totals[id],...model.evaluate(id)})).sort((a,b)=>(b.gain??-999)-(a.gain??-999)||b.count-a.count).slice(0,20);
}
function computeWaiverRows(){try{return sharedWaivers(data,league(),{...prefs,waiverExcluded,protectStarters,samePositionDrops})}catch{return []}}
function waiverFilterPositions(l){
 const slots=activeSlots(l);
 return [...new Set([...waiverPositions,...slots.flatMap(slot=>SLOT_POSITIONS[slot]||[slot])])];
}
function waiverFilters(l){const positions=waiverFilterPositions(l);
 return `<div class="waiver-position-filters">${[['add','Pick up'],['drop','May drop']].map(([side,label])=>{
 const excluded=waiverExcluded[side],included=positions.filter(p=>!excluded.includes(p)),preset=!included.length?'none':included.length===positions.length?'all':positions.every(p=>excluded.includes(p)===(p==='K'))?'no-kickers':positions.every(p=>excluded.includes(p)===!['RB','WR','TE'].includes(p))?'flex':'custom';
 return `<fieldset class="position-group waiver-position-group"><legend>${label}</legend><div class="waiver-position-options"><select class="select waiver-preset" aria-label="${label} position preset" data-waiver-preset="${side}">${[['all','All positions'],['no-kickers','Everything except kickers'],['flex','RB, WR & TE'],['none','None'],['custom','Custom selection']].map(([id,text])=>`<option value="${id}" ${preset===id?'selected':''} ${id==='custom'?'disabled':''}>${text}</option>`).join('')}</select><div class="position-options">${positions.map(p=>`<label class="position-choice"><input type="checkbox" id="waiver-${side}-${esc(p)}" data-waiver-position="${side}" value="${esc(p)}" ${excluded.includes(p)?'':'checked'}><span>${esc(p)}</span></label>`).join('')}</div></div></fieldset>`;
 }).join('')}</div>`;
}
function waivers(){
 const l=league(),weeks=waiverWindow(),future=waiverHorizon!=='current',state=waiverState?.key===waiverKey()?waiverState:null;
 const ready=!future||!!state?.outlook,rows=ready?waiverRows().filter(r=>!waiverUpgradesOnly||r.status==='upgrade'):[];
 const range=weeks.length?(weeks.length===1?`Week ${weeks[0]}`:`Weeks ${weeks[0]}–${weeks.at(-1)}`):'No remaining weeks';
 const summary=[waiverExcluded.add.length?`Pickups: no ${waiverExcluded.add.join(', ')}`:'Pickups: all',waiverExcluded.drop.length?`Drops: no ${waiverExcluded.drop.join(', ')}`:'Drops: all',waiverUpgradesOnly?'Upgrades only':null].filter(Boolean).join(' · ');
 return pageHead('Waiver wire','Find help now, next week, or for the season ahead.',`<select class="select" aria-label="Analysis league" id="analysis-league">${leagueOptions(l.league_id)}</select>`)+`
 <div class="waiver-toolbar"><label>Plan for <select class="select" id="waiver-horizon"><option value="current" ${waiverHorizon==='current'?'selected':''}>This week</option><option value="next" ${waiverHorizon==='next'?'selected':''}>Next week</option><option value="season" ${waiverHorizon==='season'?'selected':''}>Rest of season</option></select></label><span class="muted small">${range}${data.demo?' · Sample data':''}</span><button class="secondary" id="refresh-waiver" ${state?.loading||busy?'disabled':''}>Refresh outlook</button></div>
 <details class="panel waiver-controls waiver-settings" id="waiver-settings"><summary>Filters & protections <span>${esc(summary)} · Saved</span></summary><div class="waiver-settings-body">${waiverFilters(l)}<div class="waiver-rules"><label class="checkline"><input type="checkbox" id="waiver-upgrades-only" ${waiverUpgradesOnly?'checked':''}>Only show lineup upgrades</label><label class="checkline"><input type="checkbox" id="protect-starters" ${protectStarters?'checked':''}>Protect current starters</label><label class="checkline"><input type="checkbox" id="same-position-drops" ${samePositionDrops?'checked':''}>Only drop the same position</label><label class="checkline">Season ends <select class="select" id="waiver-end-week">${[17,18].map(w=>`<option value="${w}" ${waiverEndWeek===w?'selected':''}>Week ${w}</option>`).join('')}</select></label></div>${waiverProtectionControls(l)}</div></details>
 ${!ready?`<div class="empty" role="status"><h3>${state?.error?esc(state.error):'Loading waiver outlook…'}</h3><p>${state?.error?'Use Refresh outlook to retry.':'Loading weekly projections and bye weeks. Saved filters still apply.'}</p></div>`:`<div class="panel table-wrap waiver-table"><table><thead><tr><th>PLAYER</th><th>ADDS / 24H</th><th>${weeks.length>1?'TOTAL PROJ.':'PROJ.'}</th><th>${weeks.length>1?'TOTAL LINEUP GAIN':'LINEUP GAIN'}</th><th>SUGGESTED MOVE</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${playerChip(r.id,`<div class="muted small">${esc(data.players[r.id].team||'FA')} · ${esc(data.players[r.id].position)}${data.players[r.id].injury_status?' · '+esc(data.players[r.id].injury_status):''}</div>`)}</td><td>${r.count?r.count.toLocaleString():'—'}</td><td>${fmt(r.projection)}</td><td class="${r.gain>0?'gain':'muted'}">${r.gain===null?'—':signed(r.gain)}${r.weekly&&weeks.length>1?`<details class="waiver-weekly"><summary>${signed(r.gain/weeks.length)}/wk · ${r.starts} starts</summary>${r.weekly.map(w=>`<div>W${w.week}: ${signed(w.gain)}${w.starts?' · starts':''}</div>`).join('')}</details>`:''}</td><td>${r.status==='upgrade'?(r.drop?`Drop ${esc(pname(r.drop))}`:'Add to open roster spot'):`<span class="muted small">${({unavailable:'Insufficient projections',no_safe_drop:'No eligible drop',no_gain:'No lineup upgrade'})[r.status]}</span>`}</td><td><button class="pin ${pins.has(r.id)?'on':''}" data-pin="${esc(r.id)}" aria-label="Watch ${esc(pname(r.id))}">${pins.has(r.id)?'★':'☆'}</button></td></tr>`).join('')}</tbody></table>${!rows.length?empty(waiverUpgradesOnly?'No lineup upgrades match':'No available players match','Adjust Filters & protections to broaden your search.'):''}</div>`}
 <details class="data-details"><summary>How ${range.toLowerCase()} recommendations work</summary><p>${future?'Each week gets its own optimized lineup using that week’s projections and bye schedule. The same pickup and drop are held throughout the selected window. Current game locks do not apply to future lineups.':'Uses this week’s optimized lineup, with started games locked.'} Only projected lineup improvements suggest a drop. Never-drop, starter and position protections still apply. Missing projections never make a player disposable. Uses available league scoring stats; projected bonuses may be incomplete. Future injuries and role changes are uncertain; estimates do not include keeper or dynasty value.${data.demo?' Demo future projections end in week 6.':''}</p><p>${l.settings?.waiver_budget?`${Math.max(0,l.settings.waiver_budget-(l.mine.settings?.waiver_budget_used||0))} of ${l.settings.waiver_budget} waiver budget remaining.`:''} Global adds are from Sleeper. Check waiver timing before making a move.</p></details>`;
}

function partners(l){return l.rosters.filter(r=>r.roster_id!==l.mine.roster_id)}
function partnerName(l,r){const u=l.users.find(u=>u.user_id===r.owner_id);return u?.metadata?.team_name||u?.display_name||'Team '+r.roster_id}
function tradeInput(l){const partner=partners(l).find(r=>String(r.roster_id)===partnerId)||partners(l)[0];if(partner)partnerId=String(partner.roster_id);return partner;}
function tradeEval(l,p,giveIds,getIds){const model=seasonModel(l);if(!model)throw Error('Load the season outlook before analyzing a trade.');return model.assessWaivers(model.evaluate(l.mine,p,giveIds,getIds),l.mine,p,{protectedA:protectedPlayers(l)})}
function tradeSearchStatus(search){
 if(!search)return '';
 const d=search.diagnostics;
 return `<details class="data-details trade-search-status"><summary>${search.ideas.length} offers · Search details${search.truncated?' · search limit reached':''}</summary><p>${search.checked} pairs checked. ${d.offeredPlayers} eligible players to send across ${d.partners} partners. ${d.incomplete} pairs lacked a complete projection. ${d.noMutualBenefit} did not improve both teams by more than 0.25 season points. ${d.waiverRejected||0} were matched or beaten by a pickup. ${d.belowMinimum} fell below your weekly minimum after pickups; ${d.valueFiltered} exceeded your value limit (these counts can overlap).</p>${search.nearMisses?.length?`<h3>Excluded offers</h3>${search.nearMisses.map(r=>`<p><strong>${esc(pname(r.give[0]))} → ${esc(pname(r.get[0]))}</strong> · ${esc(r.partner)}<br>You ${signed(r.gainA/r.weeks)}/week · Them ${signed(r.gainB/r.weeks)}/week<br>${r.filterReasons.map(esc).join(' · ')}${[r.waiverA,r.waiverB].some(w=>w?.add)?`<br>Pickup alternatives: ${[r.waiverA,r.waiverB].map((w,i)=>w?.add?`${i===0?'You':'Them'}: ${esc(pname(w.add))} (${signed(w.gain)} season points${w.drop?`, drop ${esc(pname(w.drop))}`:''})`:'').filter(Boolean).join(' · ')}`:''}</p>`).join('')}`:''}</details>`;
}
function tradeFitExplanation(r){
 if(r.give.length!==1||r.get.length!==1||r.weekly.some(w=>w.outgoingStarts===undefined))return '';
 const count=key=>r.weekly.filter(w=>w[key]).length;
 return `<h4>Projected starts</h4><div class="table-wrap"><table><thead><tr><th scope="col">Roster</th><th scope="col">Outgoing player</th><th scope="col">Incoming player</th></tr></thead><tbody><tr><th scope="row">Yours</th><td>${count('outgoingStarts')} / ${r.weeks}</td><td>${count('incomingStarts')} / ${r.weeks}</td></tr><tr><th scope="row">Theirs</th><td>${count('partnerOutgoingStarts')} / ${r.weeks}</td><td>${count('partnerStarts')} / ${r.weeks}</td></tr></tbody></table></div>`;
}
function tradeWaiverDetails(r){
 if(!r.waiverA||!r.waiverB)return '';
 const sides=[r.waiverA,r.waiverB],gains=tradeGains(r);
 return `<h4>Free-agent alternatives</h4><div class="table-wrap"><table><thead><tr><th scope="col">Without trading</th><th scope="col">You</th><th scope="col">Them</th></tr></thead><tbody><tr><th scope="row">Pick up</th>${sides.map(w=>`<td>${w.add?esc(pname(w.add)):w.status==='unknown'?'Unknown':'None found'}</td>`).join('')}</tr><tr><th scope="row">Drop</th>${sides.map(w=>`<td>${w.drop?esc(pname(w.drop)):w.add?'Open spot':'—'}</td>`).join('')}</tr><tr><th scope="row">Pickup gain</th>${sides.map(w=>`<td>${w.status==='unknown'?'Unknown':signed(w.gain)}</td>`).join('')}</tr><tr><th scope="row">Trade advantage</th><td>${r.waiverA.status==='unknown'?'Unknown':signed(gains.a)}</td><td>${r.waiverB.status==='unknown'?'Unknown':signed(gains.b)}</td></tr></tbody></table></div><p>Season points. Each alternative keeps the outgoing trade player and uses one fixed pickup and bench drop. Current starters and your protected players are kept.</p><p>Checks the top five projected free agents per incoming position plus weekly leaders, with complete forecasts. Waiver priority, claim costs, and future availability are not modeled.${sides.some(w=>w.missing)?' Players with incomplete forecasts are excluded.':''}${sides.some(w=>w.status==='unknown')?' Missing waiver forecasts leave that team’s ranking unadjusted.':''}</p>`;
}
function tradeSummary(r){
 const reasons=realismReasons(r,{minGain:tradeMinGain,maxGap:tradeMaxGap});
 const flags=[...([r.waiverA,r.waiverB].some(w=>w?.status==='unknown')?['Limited waiver data']:[]),...([r.waiverA,r.waiverB].some(w=>w?.gain>0)?['Pickup alternative']:[]),...(r.valueGap>.4?['Large value gap']:[]),...(Math.abs(r.gainB)<.01?['Neutral for partner']:Math.min(r.gainA,r.gainB)>=0&&Math.min(r.gainA,r.gainB)/r.weeks<1?['Small weekly gain']:[]),...(reasons.length?['Outside your limits']:[])];
 const players=ids=>ids.map(id=>playerChip(id,`<span class="muted">${esc([data.players[id]?.position,data.players[id]?.team].filter(Boolean).join(' · '))}</span>`,'h3')).join('');
 const key=JSON.stringify([r.partnerId||r.partner,r.give,r.get]);
 return `<article class="panel trade-offer" tabindex="-1" aria-label="${esc(r.give.map(pname).join(' + '))} for ${esc(r.get.map(pname).join(' + '))}"><header class="trade-offer-header"><strong>${esc(r.partner||'Selected partner')}</strong><span>Weeks ${r.weekly[0].week}–${r.weekly.at(-1).week}</span></header><div class="trade-exchange"><div><span class="trade-label">You send</span>${players(r.give)}</div><span class="trade-arrow" aria-hidden="true">⇄</span><div><span class="trade-label">You receive</span>${players(r.get)}</div></div><div class="trade-points-label">Projected season gain</div><dl class="trade-metrics">${[['You',r.gainA],['Them',r.gainB],['Combined',r.gainA+r.gainB]].map(([label,value])=>`<div><dt>${label}</dt><dd class="${value>0?'gain':value<0?'loss':''}">${signed(value)}</dd></div>`).join('')}</dl>${flags.length?`<div class="trade-flags">${flags.map(f=>`<span>${f}</span>`).join('')}</div>`:''}<details class="trade-breakdown" data-trade-detail="${esc(key)}"><summary>Trade details</summary><div class="trade-detail-body"><dl class="trade-detail-metrics"><div><dt>Ranking score</dt><dd>${fmt(tradeScore(r,penalty))}</dd></div><div><dt>Value gap</dt><dd>${r.valueGap===null?'Unavailable':fmt(r.valueGap*100)+'%'}</dd></div></dl><p>Score = your advantage over pickups + ${Math.round((1-penalty)*100)}% of theirs.</p>${tradeWaiverDetails(r)}${reasons.length?`<p class="attention">${reasons.map(esc).join(' · ')}</p>`:''}${flags.includes('Small weekly gain')?'<p>At least one team gains less than 1 point per week.</p>':''}${flags.includes('Neutral for partner')?'<p>Their projected lineup does not improve.</p>':''}${tradeFitExplanation(r)}<h4>Weekly gain</h4><div class="table-wrap"><table><thead><tr><th scope="col">Week</th><th scope="col">You</th><th scope="col">Them</th><th scope="col">Combined</th></tr></thead><tbody>${r.weekly.map(w=>`<tr><th scope="row">${w.week}</th><td>${signed(w.gainA)}</td><td>${signed(w.gainB)}</td><td>${signed(w.gainA+w.gainB)}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">Average</th><td>${signed(r.gainA/r.weeks)}</td><td>${signed(r.gainB/r.weeks)}</td><td>${signed((r.gainA+r.gainB)/r.weeks)}</td></tr></tfoot></table></div><h4>Player value</h4><dl class="trade-detail-metrics"><div><dt>You send</dt><dd>${fmt(r.offeredValue)}</dd></div><div><dt>You receive</dt><dd>${fmt(r.receivedValue)}</dd></div></dl><p>Projected points above available replacements. This is not a market price or acceptance estimate.</p></div></details></article>`;
}
function tradeResultKey(l,model){return JSON.stringify([identity(model),tradeExcluded,tradeMinGain,tradeMaxGap,protectedPlayers(l),partners(l).map(p=>[p.roster_id,partnerName(l,p)])])}
function rankTrades(ideas){return ideas?[...ideas].sort((a,b)=>compareTradeIdeas(a,b,penalty)).slice(0,tradeVisible):null}
function tradePageHeader(title,description,l,model,weeks,state){
 const status=state?.loading?'Loading projections…':state?.error?esc(state.error):model?`Weeks ${weeks[0]}–${weeks.at(-1)}`:'Projections not loaded';
 return pageHead(title,description,`<select class="select" aria-label="Analysis league" id="analysis-league">${leagueOptions(l.league_id)}</select>`)+`<div class="season-status trade-season-status"><details class="data-details"><summary><span id="season-load-status">${status}</span> · Projection details</summary><p>Trades start next week. Lineups use each week's Sleeper projections, league scoring, and bye weeks. Missing weeks pause analysis. Injuries and role changes remain uncertain; scoring bonuses may be incomplete.</p><p>This season only: no dynasty value or draft picks. Ranking compares the trade with a no-trade pickup for each team. Player values are projection estimates, not market prices.${data.demo?' Demo uses sample weeks 3–4.':''}</p></details><button class="secondary" id="load-trade-season" ${state?.loading?'disabled':''}>${state?.loading?'Loading…':model?'Refresh outlook':'Load outlook'}</button></div>${l.settings?.type===2?'<p class="data-alert">Dynasty league · This season only</p>':''}`;
}
function trades(){
 const l=league(),model=seasonModel(l),weeks=tradeWeeks(),state=seasonState?.key===seasonKey()?seasonState:null;
 const search=model?tradeResults.peek(tradeResultKey(l,model)):null;
 const listKey=search?JSON.stringify([tradeResultKey(l,model),penalty]):null;
 if(listKey!==tradeListKey){tradeListKey=listKey;tradeVisible=5}
 tradeSuggestions=rankTrades(search?.ideas);
 return tradePageHeader('Auto trades','More points for both teams.',l,model,weeks,state)+`<div class="panel trade-search-tools"><button class="primary" id="suggest-trades" ${!model?'disabled':''}>Find trades →</button><details id="trade-settings" class="trade-settings"><summary>Filters & ranking</summary><div class="trade-settings-body">${tradeFilters(l)}<div class="trade-realism"><label>Minimum gain over pickups <select class="select" id="trade-min-gain">${[0,.5,1,2,3,5,10].map(n=>`<option value="${n}" ${n===tradeMinGain?'selected':''}>${n} points / week</option>`).join('')}</select></label><label>Player-value balance <select class="select" id="trade-max-gap">${[[1,'No limit'],[.15,'15% · strict'],[.25,'25% · balanced'],[.4,'40% · flexible']].map(([n,label])=>`<option value="${n}" ${n===tradeMaxGap?'selected':''}>${label}</option>`).join('')}</select></label><label>Season ends <select class="select" id="trade-end-week">${[17,18].map(n=>`<option value="${n}" ${n===tradeEndWeek?'selected':''}>Week ${n}</option>`).join('')}</select></label></div><div class="trade-controls"><label for="penalty">Bias toward your gain <strong id="penalty-label">${Math.round(penalty*100)}%</strong></label><input id="penalty" type="range" min="0" max="100" step="5" value="${penalty*100}"></div><p class="muted small">0% favors combined gain. 100% favors your gain. Both teams must beat their pickup alternatives.</p><button class="secondary" id="trade-fit-defaults">Reset trade settings</button><p class="muted small trade-save-note">Settings save automatically.</p></div></details></div>${tradeSearchStatus(search)}${tradeSuggestions===null?'':tradeSuggestions.length?`<p class="trade-results-label">Showing ${tradeSuggestions.length} of ${search.ideas.length} offers · Ranked by adjusted gain</p>`+tradeSuggestions.map(r=>tradeSummary(r)).join('')+`<div class="trade-pagination">${tradeSuggestions.length<search.ideas.length?`<button class="secondary" id="more-trades">Show ${Math.min(5,search.ideas.length-tradeSuggestions.length)} more ${search.ideas.length-tradeSuggestions.length===1?'offer':'offers'}</button>`:'<span>All offers shown</span>'}</div>`:search.diagnostics.waiverRejected>0&&search.diagnostics.waiverRejected===search.diagnostics.mutual?empty('Pickups beat these trades','Open Search details to see the available alternatives.'):empty('No offers match these settings','Broaden your filters or review search details.')}`;
}
function tradeBuilder(){
 const l=league(),p=tradeInput(l),model=seasonModel(l),weeks=tradeWeeks(),state=seasonState?.key===seasonKey()?seasonState:null;
 if(tradeManual&&tradeManual.model!==model)tradeManual=null;
 return tradePageHeader('Trade builder','Choose a package and compare its remaining-season impact.',l,model,weeks,state)+`<details class="data-details" id="builder-filters"><summary>Player filters & season window</summary>${tradeFilters(l)}<label class="checkline">Season ends <select class="select" id="trade-end-week">${[17,18].map(n=>`<option value="${n}" ${n===tradeEndWeek?'selected':''}>Week ${n}</option>`).join('')}</select></label></details><div class="section-bar"><h2>Choose your trading partner</h2><select class="select" id="trade-partner" aria-label="Trade partner">${partners(l).map(r=>`<option value="${r.roster_id}" ${String(r.roster_id)===partnerId?'selected':''}>${esc(partnerName(l,r))}</option>`).join('')}</select></div><p class="muted small">Player totals cover weeks ${weeks[0]||'—'}–${weeks.at(-1)||'—'}. Package trades must fit both rosters.</p>${p?`<div class="split">${[[l.mine,'You send',give,'give'],[p,'You receive',get,'get']].map(([r,title,selected,type])=>`<div class="panel"><h3>${title}</h3><div class="trade-picks">${tradeCandidates(r,type).map(id=>`<label class="list-choice"><span class="checkline"><input type="checkbox" data-trade="${type}" value="${esc(id)}" ${selected.includes(id)?'checked':''}>${playerChip(id,'','span')}</span><span class="muted small">${esc(data.players[id]?.position)} · ${fmt(model?.totals[id])}</span></label>`).join('')||'<p class="muted small">No players match these position filters.</p>'}</div></div>`).join('')}</div><button class="primary" id="analyze-trade" ${!model?'disabled':''}>Analyze season impact</button>${tradeManual?`<div style="margin-top:20px">${tradeSummary(tradeManual)}</div>`:''}`:empty('No trading partners found')}`;
}

function defenses(){
 const l=league();if(!activeSlots(l).includes('DEF'))return analysisHeader('Defense planner','Five weeks of matchups, compared with the weekly median.')+empty('This league does not start team defenses','Select a league with a DEF slot.');
 const availability=defenseAvailability(l,data.players),weeks=defenseWeeks(data.week);
 const outlook=defenseOutlook({players:data.players,projections:data.projections,schedules:data.schedules,weeks,scoring:l.scoring_settings});
 const rank=Object.keys(availability).map(id=>({id,vals:weeks.map(w=>outlook[w].rows[id]?.points??null)})).sort((a,b)=>b.vals.reduce((s,v)=>s+(v??0),0)-a.vals.reduce((s,v)=>s+(v??0),0));
 const usable=rank.filter(r=>availability[r.id].canUse);
 let bestPair=null;
 for(const a of usable)for(const b of usable){if(a.id>=b.id||[...a.vals,...b.vals].some(x=>x===null))continue;const total=a.vals.reduce((s,v,i)=>s+Math.max(v,b.vals[i]),0);if(!bestPair||total>bestPair.total)bestPair={a,b,total}}
 const bestSingle=usable.filter(r=>r.vals.every(v=>v!==null)).sort((a,b)=>b.vals.reduce((s,v)=>s+v,0)-a.vals.reduce((s,v)=>s+v,0))[0];
 return analysisHeader('Defense planner',`Weeks ${weeks[0]}–${weeks.at(-1)} · All defenses, with availability in this league.`)+`${bestPair&&bestSingle?`<div class="panel decision"><div><div class="eyebrow">BEST TWO-DEFENSE ROTATION · ${weeks.length} WEEKS</div><h2>${esc(bestPair.a.id)} + ${esc(bestPair.b.id)}</h2><p class="muted small">${weeks.map((w,i)=>`Week ${w}: ${bestPair.a.vals[i]>=bestPair.b.vals[i]?bestPair.a.id:bestPair.b.id}`).join(' · ')}</p></div><div><div class="big-number gain">${signed(bestPair.total-bestSingle.vals.reduce((s,v)=>s+v,0))}</div><div class="muted small">over best single defense</div></div></div>`:`<p class="data-alert">${busy?'Loading the five-week outlook…':`A rotation needs projections for all ${weeks.length} weeks. Available weeks are shown below.`}</p>`}
 <div class="defense-legend" aria-label="Defense availability colors"><span>Team names</span><span class="defense-owner-available">Available</span><span class="defense-owner-other">Rostered elsewhere</span><span class="defense-owner-mine defense-your-team">Your team</span></div>
 <div class="defense-legend" aria-label="Defense projection color scale"><span>Points vs weekly median</span>${[['poor','−3 or less'],['weak','−3 to −1'],['neutral','Within 1'],['good','+1 to +3'],['strong','+3 or more']].map(([tone,label])=>`<span class="defense-key defense-${tone}">${label}</span>`).join('')}</div>
 <div class="panel table-wrap defense-table-wrap"><table class="week-table defense-table"><thead><tr><th scope="col">DEFENSE</th>${weeks.map(w=>`<th scope="col">WEEK ${w}<span class="defense-median">Median ${fmt(outlook[w].median)}</span><span class="defense-sample">${outlook[w].count} defenses</span></th>`).join('')}</tr></thead><tbody>${rank.map(r=>`<tr><th scope="row" class="defense-owner-${availability[r.id].status}" title="${esc(availability[r.id].status==='other'?partnerName(l,l.rosters.find(owner=>owner.roster_id===availability[r.id].rosterId)):'')}"><span class="defense-name">${esc(pname(r.id))}</span><span class="defense-team">${esc(r.id)}</span><span class="defense-ownership ${availability[r.id].status==='mine'?'defense-your-team':''}">${({mine:'Your team',other:'Rostered elsewhere',available:'Available'})[availability[r.id].status]}</span></th>${weeks.map(w=>{
 const cell=outlook[w].rows[r.id],p=data.projections[w]?.[r.id],g=data.schedules[w]?.[data.players[r.id]?.team||r.id];
 const delta=cell.delta===null?'No projection':Math.abs(cell.delta)<.05?'At median':`${fmt(Math.abs(cell.delta))} ${cell.delta>0?'above':'below'} median`;
 return `<td class="defense-cell defense-${cell.tone}"><strong>${cell.bye?'BYE':fmt(cell.points)}</strong><div class="defense-opponent">${cell.bye?'No game':g?`${g.home?'vs':'@'} ${esc(g.opponent)}`:p?.opponent?'vs '+esc(p.opponent):'Schedule unavailable'}</div><div class="defense-delta">${cell.bye?'Not in median':delta}</div></td>`;
 }).join('')}</tr>`).join('')}</tbody></table></div>
 <p class="muted small">Each median uses all NFL defenses with a projection that week, including other teams’ rostered defenses, scored for this league. Byes are excluded; unavailable projections stay uncolored. Green is above median, orange is below.</p>
 <details class="data-details"><summary>Rotation & roster costs</summary><p>Rotations use only your active-roster defenses and available pickups; defenses rostered elsewhere are shown for comparison only. A second defense costs a bench spot. Rotation gain does not subtract drop value, waiver costs, or pickup restrictions. Confirm those costs before making a move.</p></details>`;
}

function settings(){return `<div class="panel"><h2>Agents & updates</h2><p>Connect coding agents, schedule summaries, and choose important-event notifications.</p><a class="secondary" href="/integrations.html">Open integration settings →</a></div>`+pageHead('My leagues','One account. Every team you care about.',`<button class="primary" data-connect>${data.demo?'Connect Sleeper':'Switch account'}</button>`)+`<div class="panel"><div class="section-bar"><div><h2 style="margin-bottom:6px">${data.demo?'Explore three sample leagues':esc(data.user.username)}</h2><p class="muted small">Choose which leagues appear in your watchroom and analysis.</p></div><span class="pill ${data.demo?'demo':'live'}">${data.demo?'SAMPLE DATA':'CONNECTED'}</span></div>${data.leagues.map((l,i)=>`<label class="league-settings"><input type="checkbox" data-league-toggle="${esc(l.league_id)}" ${l.enabled?'checked':''}><div style="flex:1"><strong>${esc(l.name)}</strong><div class="muted small">${scoring(l)} · ${l.rosters.length} teams · ${l.settings?.type===2?'Dynasty':l.settings?.type===1?'Keeper':'Redraft'}</div></div>${!data.demo?`<a href="https://sleeper.com/leagues/${esc(l.league_id)}" target="_blank" rel="noopener" class="link-external">Open ↗</a>`:''}</label>`).join('')}</div><div class="split"><div class="panel"><h3>Made for game day</h3><p class="muted small">Pin players for quick scanning. Use Focus mode for a larger watchroom. Include opponents to spot players who help one team and hurt another.</p></div><div class="panel"><h3>About your data</h3><p class="muted small">Public Sleeper data is read-only. Scores refresh every 45 seconds while this tab is visible; they may trail the broadcast. NFL game status comes from ESPN. Projections are cached for one hour, trends for 15 minutes, and player details for 24 hours. Saved data survives page reloads. Refresh bypasses score and projection caches; Refresh outlook reloads future weeks.</p></div></div><div class="panel"><h3>Prototype limits</h3><p class="muted small">Projection access is experimental and can change. Advice uses expected points, not a calibrated win probability. Advanced bonuses, dynasty values, FAAB bids are not yet included. External notifications require the optional background service. Trade estimates use future weekly projections and replacement value, not trade-market prices. “Unavailable” never means zero.</p></div>${!data.demo?'<button class="secondary disconnect" id="disconnect">Disconnect and return to demo</button>':''}`;}
async function connect(username){if(serviceMode){location.href='/integrations.html';return}const run=++connectRun,button=$('#connect-form button[type=submit]');button.disabled=true;button.textContent='Finding your leagues…';$('#connect-error').textContent='';try{const found=await api.discover(username),week=Math.max(1,Math.min(18,Number(found.nfl.week)||1));const [players,details]=await Promise.all([api.loadPlayers(),Promise.allSettled(found.leagues.map(l=>api.leagueDetails(l,found.user.user_id,week)))]);if(run!==connectRun)return;const leagues=details.filter(r=>r.status==='fulfilled').map(r=>({...r.value,enabled:!(prefs.disabled||[]).includes(r.value.league_id)&&r.value.status!=='complete'}));if(!leagues.length)throw Error('No leagues could be loaded. Please refresh and try again.');if(!leagues.some(l=>l.enabled))leagues.forEach(l=>l.enabled=true);data={user:found.user,nfl:found.nfl,week,players,leagues,projections:{},games:{},schedules:{},trends:[],updatedAt:Date.now(),demo:false,errors:details.flatMap((r,i)=>r.status==='rejected'?[`Could not load ${found.leagues[i].name}.`]:[])};leagueId=leagues.some(l=>l.league_id===prefs.analysisLeague&&l.enabled)?prefs.analysisLeague:leagues.find(l=>l.enabled).league_id;watchLeague=leagues.some(l=>l.league_id===prefs.watchLeague&&l.enabled)?prefs.watchLeague:'all';give=[];get=[];tradeManual=null;tradeSuggestions=null;prefs.username=found.user.username;savePrefs();$('#connect').close();observeScores();render();await refresh(true);if(isTradeView())ensureTradeOutlook();if(view==='waivers')ensureWaiverOutlook();toast(`Connected ${leagues.length} league${leagues.length===1?'':'s'}.`);}catch(e){if(run===connectRun){$('#connect-error').textContent=e.message;if(!$('#connect').open)toast('Could not reconnect: '+e.message)}}finally{button.disabled=false;button.textContent='Find my leagues →';}}
async function refresh(full=false,force=false){
 if(serviceMode){if(busy)return;busy=true;try{const response=await fetch(force?'/api/v1/refresh':'/api/v1/client',{method:force?'POST':'GET'});if(!response.ok)throw Error('Service refresh failed. Open Agents & updates to check the connection.');const result=await response.json();data=result.data;serviceSettings=result.settings;if(!data.leagues.some(l=>l.league_id===leagueId))leagueId=data.leagues[0]?.league_id;observeScores()}catch(e){toast(e.message)}finally{busy=false;render();if(isTradeView()&&data.leagues.some(l=>l.enabled))ensureTradeOutlook();if(view==='waivers'&&data.leagues.some(l=>l.enabled))ensureWaiverOutlook()}return}

 if(busy||data.demo){if(data.demo)toast('Demo scores are illustrative. Connect Sleeper for live updates.');return}
 busy=true;render();const current=data,userId=data.user.user_id,week=data.week,season=data.nfl.season,weeks=defenseWeeks(week);
 const jobs=data.leagues.map((l,i)=>({type:'league',i,request:api.leagueDetails(l,userId,week,{force})}));
 jobs.push({type:'schedule',week,request:api.scoreboard(season,week,{force})});
 if(full){for(const w of weeks){jobs.push({type:'projection',week:w,request:api.projections(season,w,{force})});if(w!==week)jobs.push({type:'schedule',week:w,request:api.scoreboard(season,w,{ttl:3600000,force})})}jobs.push({type:'trends',request:api.trends({force})})}
 const results=await Promise.allSettled(jobs.map(j=>j.request));if(current!==data){busy=false;return}
 const errors=[];let synced=false;
 results.forEach((result,i)=>{const job=jobs[i],ok=result.status==='fulfilled';
  if(job.type==='league'){if(ok){data.leagues[job.i]={...result.value,enabled:data.leagues[job.i].enabled};synced=true}else errors.push(`${data.leagues[job.i].name}: refresh failed; showing previous scores.`)}
  if(job.type==='schedule'){if(ok){data.schedules[job.week]=result.value;if(job.week===week)data.games=result.value}else{delete data.schedules[job.week];errors.push(`Week ${job.week} NFL schedule unavailable.${job.week===week?' Previous game status may be stale.':''}`)}}
  if(job.type==='projection'){if(ok)data.projections[job.week]=result.value;else{delete data.projections[job.week];errors.push(`Week ${job.week} projections unavailable.`)}}
  if(job.type==='trends'){if(ok)data.trends=result.value;else errors.push('Trending adds are unavailable.')}
 });
 data.errors=errors;if(synced)data.updatedAt=Date.now();busy=false;observeScores();render();if(isTradeView())ensureTradeOutlook();if(view==='waivers')ensureWaiverOutlook();
}

async function suggestTrades(){
 const l=league(),model=seasonModel(l);if(!model){toast('Load the season outlook first.');return}
 const resultKey=tradeResultKey(l,model),cached=tradeResults.peek(resultKey);if(cached){tradeSuggestions=rankTrades(cached.ideas);render();return}
 const run=++tradeRun,key=seasonKey(),btn=$('#suggest-trades');btn.disabled=true;btn.textContent='Comparing the season…';
 await new Promise(r=>setTimeout(r,20));
 try{const result=await findTradeIdeas(data,l,model,{tradeExcluded,tradeMinGain,tradeMaxGap,tradeOwnBias:penalty,waiverProtected:prefs.waiverProtected},{limit:10000,cancelled:()=>run!==tradeRun||seasonKey()!==key||league()?.league_id!==l.league_id||seasonModel(league())!==model||tradeResultKey(league(),model)!==resultKey});
  if(result.cancelled)return;const ideas=result.ideas;
  tradeResults.set(resultKey,result);tradeSuggestions=rankTrades(ideas);render();
 }catch(e){toast(e.message);render()}
}

document.addEventListener('click',e=>{const t=e.target;if(t.closest('#open-theme')){themePicker();$('#theme-dialog').showModal();$('#theme-team').focus();return}if(t.closest('#close-theme')){$('#theme-dialog').close();$('#open-theme')?.focus();return}if(t.closest('#reset-theme')){selectTheme('default');return}const n=t.closest('[data-nav]');if(n){view=n.dataset.nav;rememberPage();render();if(isTradeView())ensureTradeOutlook();if(view==='waivers')ensureWaiverOutlook();window.scrollTo({top:0});return}if(t.closest('[data-connect]')){if(serviceMode){location.href='/integrations.html';return}$('#username').value=prefs.username||'';$('#connect-error').textContent='';$('#connect').showModal();$('#username').focus()}if(t.closest('#cancel-connect')){connectRun++;$('#connect').close()}if(t.closest('#score-effects')){prefs.scoreEffects=prefs.scoreEffects===false;savePrefs();render()}if(t.closest('#preview-score')){previewPlayer=$('#players .player-card')?.dataset.playerId||null;if(previewPlayer){prefs.scoreEffects=true;savePrefs();scheduleScoreCleanup();render();toast('Highlight preview only — player scores are unchanged.')}}if(t.closest('#focus')){focus=!focus;render()}const f=t.closest('[data-filter]');if(f){filter=f.dataset.filter;savePrefs();render()}const p=t.closest('[data-pin]');if(p){pins.has(p.dataset.pin)?pins.delete(p.dataset.pin):pins.add(p.dataset.pin);savePrefs();render()}if(t.closest('#refresh'))refresh(true,true);if(t.closest('#refresh-waiver')){if(waiverHorizon==='current')refresh(true,true);else ensureWaiverOutlook(true)}if(t.closest('#disconnect')){if(serviceMode){location.href='/integrations.html';return}connectRun++;prefs.username=null;prefs.disabled=[];data=demo();leagueId=data.leagues[0].league_id;watchLeague='all';give=[];get=[];tradeManual=null;tradeSuggestions=null;savePrefs();observeScores();render();toast('Disconnected. Sample data is now displayed.')}if(t.closest('#load-trade-season'))ensureTradeOutlook(true);if(t.closest('#trade-fit-defaults')){tradeMinGain=0;tradeMaxGap=1;penalty=.15;tradeRun++;savePrefs();render();suggestTrades()}if(t.closest('#more-trades')){const next=tradeSuggestions?.length||0;tradeVisible+=5;render();const offer=document.querySelectorAll('.trade-offer')[next];offer?.focus({preventScroll:true});offer?.scrollIntoView({block:'start'});return}if(t.closest('#suggest-trades'))suggestTrades();if(t.closest('#analyze-trade')){const l=league(),p=tradeInput(l);try{const r=tradeEval(l,p,give,get);tradeManual={...r,model:seasonModel(l),give:[...give],get:[...get],partner:partnerName(l,p)};render()}catch(e){toast(e.message)}}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){query=t.value;$('#players').innerHTML=watchCards()}if(t.id==='penalty'){penalty=Number(t.value)/100;$('#penalty-label').textContent=Math.round(penalty*100)+'%'}});
